:root {
    /* Professional SaaS Blue Theme */
    --background: 210 20% 98%;
    --foreground: 222 47% 11%;

    --card: 0 0% 100%;
    --card-foreground: 222 47% 11%;

    --popover: 0 0% 100%;
    --popover-foreground: 222 47% 11%;

    /* Deep professional blue */
    --primary: 221 83% 53%;
    --primary-foreground: 210 40% 98%;

    /* Light gray-blue for secondary */
    --secondary: 210 40% 96%;
    --secondary-foreground: 222 47% 11%;

    --muted: 210 40% 96%;
    --muted-foreground: 215 16% 47%;

    /* Teal accent for highlights */
    --accent: 173 80% 40%;
    --accent-foreground: 210 40% 98%;

    --destructive: 0 84% 60%;
    --destructive-foreground: 210 40% 98%;

    /* Success, Warning states */
    --success: 142 76% 36%;
    --success-foreground: 210 40% 98%;
    --warning: 38 92% 50%;
    --warning-foreground: 222 47% 11%;

    --border: 214 32% 91%;
    --input: 214 32% 91%;
    --ring: 221 83% 53%;

    --radius: 0.5rem;

    /* Sidebar - Professional dark blue */
    --sidebar-background: 222 47% 11%;
    --sidebar-foreground: 210 40% 90%;
    --sidebar-primary: 221 83% 53%;
    --sidebar-primary-foreground: 0 0% 100%;
    --sidebar-accent: 222 47% 18%;
    --sidebar-accent-foreground: 210 40% 98%;
    --sidebar-border: 222 47% 20%;
    --sidebar-ring: 221 83% 53%;
    --sidebar-muted: 215 16% 60%;

    /* Custom HRM colors */
    --hrm-recruitment: 280 65% 60%;
    --hrm-attendance: 173 80% 40%;
    --hrm-payroll: 38 92% 50%;
    --hrm-employee: 221 83% 53%;

    /* Gradients */
    --gradient-primary: linear-gradient(135deg, hsl(221 83% 53%), hsl(221 83% 40%));
    --gradient-accent: linear-gradient(135deg, hsl(173 80% 40%), hsl(173 80% 30%));
    --gradient-sidebar: linear-gradient(180deg, hsl(222 47% 11%), hsl(222 47% 8%));
  }

.dark {
    --background: 222 47% 6%;
    --foreground: 210 40% 98%;

    --card: 222 47% 8%;
    --card-foreground: 210 40% 98%;

    --popover: 222 47% 8%;
    --popover-foreground: 210 40% 98%;

    --primary: 221 83% 60%;
    --primary-foreground: 222 47% 11%;

    --secondary: 217 33% 17%;
    --secondary-foreground: 210 40% 98%;

    --muted: 217 33% 17%;
    --muted-foreground: 215 20% 65%;

    --accent: 173 80% 45%;
