/**
   * X-BOS Safe Area — đối xứng tuyệt đối hai rìa (Bộ luật đối xứng V2).
   * Trục px-8 (32px) → px-12 (48px); không kéo vượt 3rem.
   */

.xevn-safe-inline {
    padding-left: clamp(2rem, 4vw + 1rem, 3rem);
    padding-right: clamp(2rem, 4vw + 1rem, 3rem);
  }

/** Workflow Canvas — nền slate-50 + lưới chấm 20px */

.safe-area-bottom {
  padding-bottom: env(safe-area-inset-bottom, 0px);
}

/* iOS-specific: prevent zoom on input focus */

@supports (-webkit-touch-callout: none) {
  input, textarea, select {
    font-size: 16px !important;
  }
}

/* Mobile table improvements */

@media (max-width: 768px) {
  .saas-table th,
  .saas-table td {
    padding: 8px 10px;
    font-size: 12px;
  }
}

